/**
 * Bundled fallback bytes for the handful of image assets the built-in
 * default brands (Boehringer Ingelheim, TG Therapeutics) reference by
 * /uploads/<filename> path in their preset JSON (see
 * client/portals/patient/config/brands/*.json). Deliberately excludes
 * Assistivan on purpose — it points at an external CDN and never touches
 * Blobs at all, and stays that way.
 *
 * These files live in git (public/uploads/) but were never actually
 * uploaded into any environment's Netlify Blobs "uploads" store through
 * the admin's Upload flow — that store is separate per environment (see
 * BRANDING_ADMIN_GUIDE.md) and isn't populated by a normal git deploy. So a
 * brand-new environment (a fresh branch deploy, or Blobs wiped) had no way
 * to serve them: serve-upload.ts reads Blobs exclusively, with no
 * filesystem fallback of its own.
 *
 * Base64-inlined into this module (imported the same way brandStore.ts
 * already inlines the preset JSON files) rather than bundled as raw files
 * via Netlify's included_files — this repo's own comments elsewhere
 * document more than one Netlify bundling/redirect mechanism that proved
 * unreliable specifically in production, so this sticks to the one pattern
 * (an ES module import) already proven to survive a real deploy here.
 *
 * serve-upload.ts falls back to this manifest only on a genuine Blobs miss,
 * and only for the exact filenames listed here — anything else still
 * 404s exactly as before. On a hit, it also writes the bytes into that
 * environment's Blobs store so every request after the first one takes the
 * normal fast Blobs path instead of hitting this fallback again.
 */

export interface BuiltinUpload {
  contentType: string;
  base64: string;
}

